/**
 * The Chandramari Group mark, inlined as a data URI.
 *
 * The PO PDF is rendered by Puppeteer with no network and no document origin,
 * so a relative path or an app URL would come out as a broken image in the
 * attachment the vendor receives. The bytes travel with the code instead.
 *
 * Generated from apps/web/public/logo.png — regenerate both together.
 */
export const BRAND_LOGO_DATA_URI =
  'data:image/png;base64,';
